import{_ as o,c as s,o as n,j as i,Y as a,t as r}from"./chunks/framework.BNTND4LZ.js";const b=JSON.parse('{"title":"gitmodules | x-cmd man (git man5) | Defining submodule properties","titleTemplate":false,"description":"x-cmd man (git man5 Manual Page) | gitmodules - Defining submodule properties","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitmodules | x-cmd man (git man5) | Defining submodule properties"}],["meta",{"name":"og:description","content":"x-cmd man (git man5 Manual Page) | gitmodules - Defining submodule properties"}]]},"headers":[],"params":{"isMan":true,"man":"gitmodules","category":"git man5","desc":"Defining submodule properties"},"relativePath":"git/man5/gitmodules.md","filePath":"git/man5/[man].md"}'),l={name:"git/man5/gitmodules.md"},u={class:"visually-hidden"};function d(t,e,m,h,c,g){return n(),s("div",null,[i("h1",u,r(t.$params.man),1),e[0]||(e[0]=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitmodules - Defining submodule properties</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p>$GIT_WORK_TREE/.gitmodules</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>.gitmodules</strong> file, located in the top-level directory of a Git working tree, is a text file with a syntax matching the requirements of <strong>git-config</strong>(1).</p><p>The file contains one subsection per submodule, and the subsection value is the name of the submodule. The name is set to the path where the submodule has been added unless it was customized with the <strong>--name</strong> option of <em>git submodule add</em>. Each submodule section also contains the following required keys:</p><p>submodule.&lt;name&gt;.path</p><blockquote><p>Defines the path, relative to the top-level directory of the Git working tree, where the submodule is expected to be checked out. The path name must not end with a <strong>/</strong>. All submodule paths must be unique within the <strong>.gitmodules</strong> file.</p></blockquote><p>submodule.&lt;name&gt;.url</p><blockquote><p>Defines a URL from which the submodule repository can be cloned. This may be either an absolute URL ready to be passed to <strong>git-clone</strong>(1) or (if it begins with <strong>./</strong> or <strong>../</strong>) a location relative to the superproject&#39;s origin repository.</p></blockquote><p>In addition, there are a number of optional keys:</p><p>submodule.&lt;name&gt;.update</p><blockquote><p>Defines the default update procedure for the named submodule, i.e. how the submodule is updated by the <strong>git submodule update</strong> command in the superproject. This is only used by <strong>git submodule init</strong> to initialize the configuration variable of the same name. Allowed values here are <em>checkout</em>, <em>rebase</em>, <em>merge</em> or <em>none</em>. See description of <em>update</em> command in <strong>git-submodule</strong>(1) for their meaning. For security reasons, the <em>!command</em> form is not accepted here.</p></blockquote><p>submodule.&lt;name&gt;.branch</p><blockquote><p>A remote branch name for tracking updates in the upstream submodule. If the option is not specified, it defaults to the remote <strong>HEAD</strong>. A special value of <strong>.</strong> is used to indicate that the name of the branch in the submodule should be the same name as the current branch in the current repository. See the <strong>--remote</strong> documentation in <strong>git-submodule</strong>(1) for details.</p></blockquote><p>submodule.&lt;name&gt;.fetchRecurseSubmodules</p><blockquote><p>This option can be used to control recursive fetching of this submodule. If this option is also present in the submodule&#39;s entry in <strong>.git/config</strong> of the superproject, the setting there will override the one found in <strong>.gitmodules</strong>. Both settings can be overridden on the command line by using the <strong>--[no-]recurse-submodules</strong> option to <strong>git fetch</strong> and <strong>git pull</strong>.</p></blockquote><p>submodule.&lt;name&gt;.ignore</p><blockquote><p>Defines under what circumstances <strong>git status</strong> and the diff family show a submodule as modified. The following values are supported:</p><p>all</p><blockquote><p>The submodule will never be considered modified (but will nonetheless show up in the output of status and commit when it has been staged).</p></blockquote><p>dirty</p><blockquote><p>All changes to the submodule&#39;s work tree will be ignored, only committed differences between the <strong>HEAD</strong> of the submodule and its recorded state in the superproject are taken into account.</p></blockquote><p>untracked</p><blockquote><p>Only untracked files in submodules will be ignored. Committed differences and modifications to tracked files will show up.</p></blockquote><p>none</p><blockquote><p>No modifications to submodules are ignored, all of committed differences, and modifications to tracked and untracked files are shown. This is the default option.</p></blockquote><p>If this option is also present in the submodule&#39;s entry in <strong>.git/config</strong> of the superproject, the setting there will override the one found in <strong>.gitmodules</strong>.</p><p>Both settings can be overridden on the command line by using the <strong>--ignore-submodules</strong> option. The <strong>git submodule</strong> commands are not affected by this setting.</p></blockquote><p>submodule.&lt;name&gt;.shallow</p><blockquote><p>When set to true, a clone of this submodule will be performed as a shallow clone (with a history depth of 1) unless the user explicitly asks for a non-shallow clone.</p></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Git does not allow the <strong>.gitmodules</strong> file within a working tree to be a symbolic link, and will refuse to check out such a tree entry. This keeps behavior consistent when the file is accessed from the index or a tree versus from the filesystem, and helps Git reliably enforce security checks of the file contents.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Consider the following <strong>.gitmodules</strong> file:</p><blockquote><pre><code>[submodule &quot;libfoo&quot;]
        path = include/foo
        url = git://foo.com/git/lib.git

[submodule &quot;libbar&quot;]
        path = include/bar
        url = git://bar.com/git/lib.git
</code></pre></blockquote><p>This defines two submodules, <strong>libfoo</strong> and <strong>libbar</strong>. These are expected to be checked out in the paths <strong>include/foo</strong> and <strong>include/bar</strong>, and for both submodules a URL is specified which can be used for cloning the submodules.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-submodule</strong>(1), <strong>gitsubmodules</strong>(7), <strong>git-config</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,32))])}const f=o(l,[["render",d]]);export{b as __pageData,f as default};
